//SOUND_BEGIN
// =========================================================================
// Title: Everything's A Caustic
// Author: Wyatt
// Source: https://www.shadertoy.com/view/WdBGDm
// License: CC BY-NC-SA 3.0 (Shadertoy Default License)
//
// Note: Granular and caustic sound synthesis.
//       Adapted for Desktop GLSL Audio.
// =========================================================================

#define PI2_LOCAL 6.28318530718
#define M_C 261.625565
#define PW 1.05946309436

// Hash 3D per la generazione di numeri casuali (Dave Hoskins)
vec3 hash31(float p) {
   vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
   p3 += dot(p3, p3.yzx + 19.19);
   return fract((p3.xxy + p3.yzz) * p3.zyx); 
}

// Funzione generatrice della nota (Sintesi FM + Inviluppo)
float X (
    float time,
    float phase,
    float octave, 
    float note, 
    float attack,
    float sustain,
    float release,
    float nl
) {
    float phi = phase * PI2_LOCAL;
    // Calcolo della frequenza basato sul temperamento equabile
    float w = M_C * PI2_LOCAL * exp2(octave) * pow(PW, note);

    // Inviluppo ADSR semplificato
    float envelope = smoothstep(0., attack, time - phase) * smoothstep(release, 0., time - phase - attack - sustain);

    // Sintesi FM: due oscillatori dove la fase è modulata da un altro coseno
    float wave1 = cos(w * time - phi + 50. * cos(0.001 * nl * w * time));
    float wave2 = cos(0.25 * w * time - phi + 30. * cos(0.002 * nl * w * time));

    return (wave1 + wave2) * envelope;
}

// -------------------------------------------------------------------------
// MAIN SOUND
// -------------------------------------------------------------------------

vec2 mainSound( in int samp, float t ) {
    float a = 0.;
    #define N_VOICES 15.

    // Iterazione per generare polifonia e texture
    for (float i = 0.; i < N_VOICES; i++) {
        float time_idx = 0.;
        float note = 0.;
        float root = 0.;
        float octave = 1.0;
        vec3 h;
        float d = 1.0;

        // Logica temporale per creare ritmi frattali
        time_idx = floor(t);
        h = hash31(time_idx);
        root = floor(h.x * 12.) - 12.;
        h = hash31(time_idx + i);

        // Suddivisione ritmica casuale (stocastica)
        if (h.x > 0.4) {
            d *= 0.5;
            time_idx = floor(t);
            h = hash31(2. * time_idx + i * 100.);
            if (h.x > 0.6) {
                d *= 0.5;
                time_idx = floor(t * 2.) / 2.;
                h = hash31(20. * time_idx + i * 120.);
            }
        }

        // Selezione della nota nella scala
        note = 2. * floor(h.z * 6.) - 4.;

        // Somma delle voci
        a += 0.5 * X(t, time_idx, octave, root + note, 0.01 * d, 0.9 * d, 0.1 * d, 0.2 * h.x);
    }

    // Normalizzazione e output stereo (mono in questo caso, bilanciato su vec2)
    vec2 audio = vec2(a) / N_VOICES;

    // Fade-in iniziale e limiter finale
    return clamp(audio * smoothstep(0.0, 1.0, t), -1.0, 1.0);
}
//SOUND_END

// =========================================================================
// PRESET SHADER: QuasiCrystals - Dragon Eye
// Author: mrange
// Original Link: https://www.shadertoy.com/view/wdXfz8
// License: Creative Commons Attribution-NonCommercial-ShareAlike 3.0 Unported
// =========================================================================
// This shader combines quasicrystal noise with Fractional Brownian Motion (fBm)
// to simulate the iris texture and electrical volumetric glow of a dragon's eye.
// Integrated into SurfaceExplorer. Distributed under CC BY-NC-SA 3.0 terms.
// =========================================================================

#define PI          3.141592654
#define TAU         (2.0*PI)
#define LAYERS      6
#define FBM         3
#define LIGHTNING   3
#define DISTORT     1.4
#define TIME        iTime
#define TTIME       (TAU*TIME)

float wave(float theta, vec2 p) {
  return (cos(dot(p,vec2(cos(theta),sin(theta)))));
}

float noise(vec2 p, float time) {
  float sum = 0.;
  float a = 1.0;
  for(int i = 0; i < LAYERS; ++i)  {
    float theta = float(i)*PI/float(LAYERS);
    sum += wave(theta, p)*a;
    a*=DISTORT;
  }

  return abs(tanh(sum+1.0+0.75*cos(time)));
}

float fbm(vec2 p, float time) {
  float sum = 0.;
  float a = 1.0;
  float f = 1.0;
  for(int i = 0; i < FBM; ++i)  {
    sum += a*noise(p*f, time);
    a *= 2.0/3.0;
    f *= 2.31;
  }

  return 0.45*(sum);
}

vec3 lightning(vec2 pos, float offset) {
  vec3 col = vec3(0.0);
  vec2 f = vec2(0);

  const float w=0.15;

  for (int i = 0; i < LIGHTNING; i++) {
    float time = TIME + 0.5*float(i);   
    float d1 = abs(offset * w / (0.0 + offset - fbm((pos + f) * 3.0, time)));
    float d2 = abs(offset * w / (0.0 + offset - fbm((pos + f) * 2.0, 0.9 * time + 10.0)));
    col += vec3(clamp(d1, 0.0, 1.0) * vec3(0.1, 0.5, 0.8));
    col += vec3(clamp(d2, 0.0, 1.0) * vec3(0.7, 0.5, 0.3));
  }

  return (col);
}

vec3 postProcess(vec3 col, vec2 q) {
  col=pow(clamp(col,0.0,1.0),vec3(0.75)); 
  col=col*0.6+0.4*col*col*(3.0-2.0*col);  // contrast
  col=mix(col, vec3(dot(col, vec3(0.33))), -0.4);  // satuation
  col*=0.5+0.5*pow(19.0*q.x*q.y*(1.0-q.x)*(1.0-q.y),0.7);  // vigneting
  return col;
}

void rot(inout vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  p = vec2(p.x*c + p.y*s, -p.x*s + p.y*c);
}

vec3 normal(vec2 p, float time) {
  vec2 v;
  vec2 w;
  vec2 e = vec2(0.00001, 0);

  vec3 n;
  n.x = fbm(p + e.xy, time) - fbm(p - e.xy, time);
  n.y = 2.0*e.x;
  n.z = fbm(p + e.yx, time) - fbm(p - e.yx, time);

  return normalize(n);
}

vec3 dragonEye(vec2 p) {
  vec2 pp = 10.0*p;

  rot(p, -0.75); 
  p *= vec2(1.1/tanh(1.0 + length(p)), 1.0);
  float l = length(p);

  float dd = 0.2 + 0.65*(-0.5 + 1.75*(0.5 + 0.5*cos(3.0*l-TTIME/12.0)))*tanh(1.0/((pow(l, 4.0) + 2.0)));
  dd *= smoothstep(9.0, 12.0, TIME-l*2.0);
  vec3 col = vec3(0.0);
  float f = fbm(pp, TIME*0.1);
  vec3 ld = normalize(vec3(p.x, 0.5, p.y));
  vec3 n = normal(pp, TIME*0.1);
  float diff = max(dot(ld, n), 0.0);
  col += vec3(0.5, 1.0, 0.8)*pow(diff, 20.0)/(0.5+dot(p, p));
  col += lightning(pp, dd);
  col *= pow(vec3(f), vec3(1.5, 5.0, 5.0));
//  col += -0.1+0.3*vec3(0.7, 0.2, 0.4)*vec3(tanh((pow(0.6/f, 10))));
  return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 q = fragCoord.xy/iResolution.xy;    
  vec2 p = -1.0 + 2.0*q;

  p.x *= iResolution.x/iResolution.y;    

  vec3 col = dragonEye(p);

  col = postProcess(col, q);

  col *= smoothstep(0.0, 4.0, TIME);

  fragColor = vec4(col, 1.0);  
}
